import java.util.HashMap;
import java.util.Map;

public class Solution {
  private static final int NONE = 0, TRIED = 1, CONFIRMED = 2, CANCELLED = 3, EMPTY = 4;

  public static int[] tccBranchLifecycle(int[] xid, int[] bid, int[] action) {
    if (xid == null || bid == null || action == null) throw new IllegalArgumentException("array length mismatch");
    int n = xid.length;
    if (bid.length != n || action.length != n) throw new IllegalArgumentException("array length mismatch");

    Map<Long, Integer> state = new HashMap<>();
    int tryOk = 0, confirmOk = 0, cancelOk = 0, emptyRollback = 0, suspended = 0;
    int orphanConfirm = 0, cancelAfterConfirm = 0, confirmAfterCancel = 0, replay = 0, business = 0;

    for (int i = 0; i < n; i++) {
      if (xid[i] < 0 || bid[i] < 0) throw new IllegalArgumentException("negative transaction id");
      if (action[i] != 0 && action[i] != 1 && action[i] != 2) {
        throw new IllegalArgumentException("unknown branch action");
      }
      long key = (long) xid[i] * 1000003L + bid[i];
      int st = state.getOrDefault(key, NONE);
      if (action[i] == 0) {
        if (st == NONE) { state.put(key, TRIED); tryOk++; business++; }
        else if (st == CANCELLED || st == EMPTY) { suspended++; }      // 防悬挂
        else { replay++; }                                            // 重复 Try：幂等
      } else if (action[i] == 1) {
        if (st == TRIED) { state.put(key, CONFIRMED); confirmOk++; business++; }
        else if (st == NONE) { orphanConfirm++; }                     // 防孤儿确认
        else if (st == CANCELLED || st == EMPTY) { confirmAfterCancel++; }
        else { replay++; }
      } else {
        if (st == TRIED) { state.put(key, CANCELLED); cancelOk++; business++; }
        else if (st == NONE) { state.put(key, EMPTY); cancelOk++; emptyRollback++; }  // 空回滚
        else if (st == CONFIRMED) { cancelAfterConfirm++; }
        else { replay++; }
      }
    }
    return new int[] {tryOk, confirmOk, cancelOk, emptyRollback, suspended,
                      orphanConfirm, cancelAfterConfirm, confirmAfterCancel, replay, business};
  }
}

