import java.util.HashMap;
import java.util.Map;

public class Solution {
  // "TCC 就是三个方法名"版：任何 cancel 都当正常回滚、任何 confirm 都当正常提交，
  // 既不认空回滚也不防悬挂 —— 于是"资源从没预留却被回滚"和"回滚之后又被提交"都算成功。
  public static int[] tccBranchLifecycle(int[] xid, int[] bid, int[] action) {
    if (xid == null || bid == null || action == null) throw new IllegalArgumentException("array length mismatch");
    int n = xid.length;
    if (bid.length != n || action.length != n) throw new IllegalArgumentException("array length mismatch");
    Map<Long, Integer> seen = new HashMap<>();
    int tryOk = 0, confirmOk = 0, cancelOk = 0, replay = 0, business = 0;
    for (int i = 0; i < n; i++) {
      if (xid[i] < 0 || bid[i] < 0) throw new IllegalArgumentException("negative transaction id");
      if (action[i] != 0 && action[i] != 1 && action[i] != 2) {
        throw new IllegalArgumentException("unknown branch action");
      }
      long key = (long) xid[i] * 1000003L + bid[i];
      int c = seen.getOrDefault(key, 0);
      if (action[i] == 0) {
        if (c == 0) { tryOk++; business++; } else { replay++; }
      } else if (action[i] == 1) {
        confirmOk++; business++;
      } else {
        cancelOk++; business++;
      }
      seen.put(key, c + 1);
    }
    return new int[] {tryOk, confirmOk, cancelOk, 0, 0, 0, 0, 0, replay, business};
  }
}
